langs = ['en', 'de', 'fr', 'ru', 'hu', 'vi', 'ar', 'es']
os.makedirs('lib/l10n', exist_ok=True)
for lang in langs:
    out = {'@@locale': lang}
    for key, t in K.items():
        assert lang in t, (key, lang)
        out[key] = t[lang]
        if lang == 'en' and key in PH:
            out['@' + key] = {'placeholders': PH[key]}
    with open(f'lib/l10n/app_{lang}.arb', 'w', encoding='utf-8') as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
        f.write('\n')
print(len(K), 'keys,', len(langs), 'languages')
